"""Validate every program generated by the browser suite with the API validator."""

import importlib.util
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location(
    "program_validation", ROOT / "custom_components/skyrc_mc3000/program_validation.py"
)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
programs = json.loads((ROOT / ".test-artifacts/generated-profiles.json").read_text())
assert len(programs) == 48
for program in programs:
    assert module.validate_program(program) == program
print(f"{len(programs)} frontend programs match the backend validator")
